import json, os, sys, market_model

a=json.load(sys.stdin)
md=os.environ["MARKET_DIR"]
limit=max(1,min(100,int(a.get("limit",20))))
query=str(a.get("query","")).lower()
category=str(a.get("category","")).lower()
shop=str(a.get("shop","")).lower()
with open(os.path.join(md,"catalog.json"),encoding="utf-8") as f:
    raw=json.load(f)
items=raw if isinstance(raw,list) else raw.get("items",raw.get("catalog",[])) if isinstance(raw,dict) else []
if isinstance(items,dict):
    items=[dict(v,sku=k) if isinstance(v,dict) else {"sku":k,"name":v} for k,v in items.items()]
def text(x):
    return " ".join(str(v) for v in x.values()).lower() if isinstance(x,dict) else str(x).lower()
catalog=[x for x in items if isinstance(x,dict) and (not query or query in text(x)) and (not category or category in text(x))]
skus={str(x.get("sku","")) for x in catalog}
rows=market_model.load_rows(md)
def field(r,*names):
    return next((str(r.get(n,"")) for n in names if r.get(n) is not None),"")
deals=[]
for r in rows:
    if not isinstance(r,dict):
        continue
    if category and category not in field(r,"category").lower():
        continue
    if shop and shop not in field(r,"shop","seller").lower():
        continue
    if query and field(r,"sku","item_sku").lower() not in skus:
        continue
    deals.append(r)
print(json.dumps({"catalog":catalog[:limit],"deals":deals[-limit:]}))
